use std::collections::{BTreeSet, HashMap};
use std::io::{self, Read, Write};

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut lines = s.lines().map(|l| l.trim()).filter(|l| !l.is_empty());

    let first: Vec<i64> = lines
        .next()
        .unwrap_or("0 0")
        .split_whitespace()
        .map(|x| x.parse().unwrap())
        .collect();
    let w = first[0].max(0) as usize;
    let n = first.get(1).copied().unwrap_or(0).max(0) as usize;

    let mut ids: Vec<i64> = Vec::with_capacity(n);
    let mut dur: Vec<i64> = Vec::with_capacity(n);
    let mut deps: Vec<Vec<i64>> = Vec::with_capacity(n);
    for _ in 0..n {
        let toks: Vec<i64> = lines
            .next()
            .unwrap()
            .split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect();
        ids.push(toks[0]);
        dur.push(toks[1]);
        deps.push(toks[2..].to_vec());
    }

    let idx: HashMap<i64, usize> = ids.iter().enumerate().map(|(i, &id)| (id, i)).collect();
    let mut indeg = vec![0usize; n];
    let mut children: Vec<Vec<usize>> = vec![Vec::new(); n];
    for i in 0..n {
        for d in &deps[i] {
            let p = idx[d];
            children[p].push(i);
            indeg[i] += 1;
        }
    }

    // Ready tasks ordered by id (smallest first).
    let mut ready: BTreeSet<(i64, usize)> = (0..n)
        .filter(|&i| indeg[i] == 0)
        .map(|i| (ids[i], i))
        .collect();

    let mut start = vec![0i64; n];
    let mut end = vec![0i64; n];
    let mut running: Vec<usize> = Vec::new();
    let mut free = w;
    let mut t = 0i64;

    loop {
        // Start as many ready tasks as there are free workers, smallest id first.
        while free > 0 {
            let next = ready.iter().next().copied();
            match next {
                Some(key) => {
                    ready.remove(&key);
                    let i = key.1;
                    start[i] = t;
                    end[i] = t + dur[i];
                    running.push(i);
                    free -= 1;
                }
                None => break,
            }
        }
        if running.is_empty() {
            break;
        }
        // Advance to the next finishing time and release everything finishing then.
        t = running.iter().map(|&i| end[i]).min().unwrap();
        let mut still = Vec::new();
        for &i in &running {
            if end[i] == t {
                free += 1;
                for &c in &children[i] {
                    indeg[c] -= 1;
                    if indeg[c] == 0 {
                        ready.insert((ids[c], c));
                    }
                }
            } else {
                still.push(i);
            }
        }
        running = still;
    }

    let mut order: Vec<usize> = (0..n).collect();
    order.sort_by_key(|&i| ids[i]);
    let makespan = (0..n).map(|i| end[i]).max().unwrap_or(0);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for i in order {
        writeln!(out, "{} {} {}", ids[i], start[i], end[i]).unwrap();
    }
    writeln!(out, "makespan {}", makespan).unwrap();
}
